// Rain Alarm
// Sounds a buzzer continuously while the rain sensor grid detects moisture.

const int RAIN_DOUT_PIN = 2;
const int BUZZER_PIN = 8;

void setup() {
  pinMode(RAIN_DOUT_PIN, INPUT);
  pinMode(BUZZER_PIN, OUTPUT);
}

void loop() {
  // Most of these boards' comparators output LOW when wet, HIGH when dry —
  // check yours with the Serial Monitor if the alarm behaves backwards.
  bool isWet = digitalRead(RAIN_DOUT_PIN) == LOW;

  if (isWet) {
    tone(BUZZER_PIN, 1000); // continuous 1kHz tone while wet
  } else {
    noTone(BUZZER_PIN);
  }
}
